/*@<v2>
  assigns \nothing;
  ensures -100000 < \result < 100000;
*/
int unknown();
int N = 100000;
int main()
{
  int i;
  int a[N];
  int b[N];
  int c[N];
  int x= unknown();
  //@ assert (x > -100000 && x < 100000);
  for(i=0;i<N;i++) {
    x = unknown();
    //@ assert (x > -100000 && x < 100000);
    a[i]=x;
    b[i]=-x;
  }
  for(i=0;i<N;i++){ /*
    loop invariant 0 <= i <= N;
    loop invariant forall j in [0,i): c[j] == 0;
    loop invariant forall j in [0,N): a[j] == -b[j];
    assign i, c[0..N-1];
    loop variant N - i;
    */
    c[i]=a[i]+b[i];
  }
  for(i=1;i<N;i++){ /*
    loop invariant 1 <= i <= N;
    loop invariant forall j in [0,N): c[j] == 0;
    assign i;
    loop variant N - i;
    */
  }
  return 0;
}
